package com.cryptoloan.loan.adapters.out.persistence;import com.cryptoloan.loan.domain.model.*;import com.cryptoloan.loan.domain.port.out.LoanPorts.Repository;import java.util.*;import org.springframework.stereotype.Component;@Component class LoanRepositoryAdapter implements Repository{private final SpringDataLoanRepository repo;LoanRepositoryAdapter(SpringDataLoanRepository repo){this.repo=repo;}public Loan save(Loan l){LoanJpaEntity e=l.id()==null?new LoanJpaEntity():repo.findById(l.id()).orElseThrow();e.requestId=l.requestId();e.borrowerEmail=l.borrowerEmail();e.borrowerName=l.borrowerName();e.amountEur=l.amountEur();e.collateralSymbol=l.collateralSymbol();e.collateralAmount=l.collateralAmount();e.minimumRatio=l.minimumRatio();e.status=l.status();e.warningSent=l.warningSent();e.lastObservedRatio=l.lastObservedRatio();e.createdAt=l.createdAt();e.approvedAt=l.approvedAt();e.liquidatedAt=l.liquidatedAt();e.contractHash=l.contractHash();return domain(repo.save(e));}public Optional<Loan>findById(Long id){return repo.findById(id).map(this::domain);}public Optional<Loan>findByRequestId(UUID id){return repo.findByRequestId(id).map(this::domain);}public List<Loan>findByBorrower(String email){return repo.findByBorrowerEmailOrderByCreatedAtDesc(email).stream().map(this::domain).toList();}public List<Loan>findAll(){return repo.findAll().stream().map(this::domain).toList();}public List<Loan>findActive(){return repo.findByStatus(LoanStatus.APPROVED).stream().map(this::domain).toList();}private Loan domain(LoanJpaEntity e){return new Loan(e.id,e.requestId,e.borrowerEmail,e.borrowerName,e.amountEur,e.collateralSymbol,e.collateralAmount,e.minimumRatio,e.status,e.warningSent,e.lastObservedRatio,e.createdAt,e.approvedAt,e.liquidatedAt,e.contractHash);}}

